// Package config loads the manager configuration (JSON, generated by the Nix module; MG-17).
package config

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/CybexBV/whombat/contracts/go/local"
)

// Config is the manager configuration file.
type Config struct {
	DeviceFile     string `json:"deviceFile"`
	ManagementKey  string `json:"managementKey"`
	ManagerVersion string `json:"managerVersion"`
	// Edition is the image's (Whombat HE-58, MG-136): "commercial" (or absent: every image before it) talks to control;
	// "community" has none (control.url ""): it takes the newest release of its own TUF repository and reports to nobody.
	Edition string `json:"edition"`
	Control struct {
		URL string `json:"url"`
	} `json:"control"`
	TUF struct {
		PinnedRoot  string `json:"pinnedRoot"`
		MetadataURL string `json:"metadataUrl"`
		TargetsURL  string `json:"targetsUrl"`
		// TargetsLayout is "" (consistent-snapshot paths under targetsUrl, one server) or "github" (LNK-24: targetsUrl
		// is https://github.com/<owner>/<repo>/releases/download/ and files are release assets). The image sets it in
		// the units' environment (EnvTargetsLayout), never in this file; the key stays readable for tests.
		TargetsLayout string `json:"targetsLayout"`
		CacheDir      string `json:"cacheDir"`
		MirrorDir     string `json:"mirrorDir"`
	} `json:"tuf"`
	StagingDir     string `json:"stagingDir"`
	JournalDir     string `json:"journalDir"`
	AssignmentPath string `json:"assignmentPath"`
	KnownGoodDir   string `json:"knownGoodDir"`
	HelperSocket   string `json:"helperSocket"`
	APISocket      string `json:"apiSocket"`
	BackupSocket   string `json:"backupSocket"`
	Network        struct {
		CandidatesDir string `json:"candidatesDir"`
		StateDir      string `json:"stateDir"`
	} `json:"network"`
	Runtime struct {
		AdminSocket string   `json:"adminSocket"`
		HealthURL   string   `json:"healthUrl"`
		SessionAddr string   `json:"sessionAddr"`
		Units       []string `json:"units"`
		User        string   `json:"user"`
	} `json:"runtime"`
	// Clients: AI client installs (CT-73, MG-33). Empty root: the manager manages no clients (older images).
	Clients struct {
		// Root is where clients are installed, readable by the runner (/persist/whombat/clients).
		Root string `json:"root"`
		// StateDir is manager-private (/persist/manager/clients): state, the last channel, download staging.
		StateDir string `json:"stateDir"`
		// ChannelKeys is the pinned channel key document (AssignmentKeys shape, CT-74).
		ChannelKeys string `json:"channelKeys"`
		// CheckSec: channel check interval besides every TUF refresh (default 3600).
		CheckSec int `json:"checkSec"`
	} `json:"clients"`
	// Licence: the signed appliance licence (LC-06, MG-34). Empty keysFile: the manager renews no licence (images
	// before contracts 0.10.0; a prod image without a pinned key set is refused at build time, NX-38).
	Licence struct {
		// KeysFile is the pinned LicenceKeySet (/etc/whombat/licence-keys.json, from the image, LC-03).
		KeysFile string `json:"keysFile"`
		// StateFile is where {token, highWater} is kept (0600, atomic); default <dir of journalDir>/licence.json,
		// i.e. /persist/manager/licence.json on the appliance.
		StateFile string `json:"stateFile"`
	} `json:"licence"`
	LockUsers []string `json:"lockUsers"`
	// Metrics: how the box is doing (MG-63). Both default from journalDir, so the Nix module sets neither (an older
	// known-good manager refuses fields it doesn't know): dir <dir of journalDir>/metrics (/persist/manager/metrics),
	// persistDir the directory above that (/persist), whose disk is measured with its parts.
	Metrics struct {
		Dir        string `json:"dir"`
		PersistDir string `json:"persistDir"`
	} `json:"metrics"`
	Host struct {
		BootIDPath    string `json:"bootIdPath"`
		CurrentSystem string `json:"currentSystem"`
		// UptimePath (/proc/uptime) and TimeSyncedPath (systemd-timesyncd's
		// /run/systemd/timesync/synchronized) feed status.report.
		UptimePath     string `json:"uptimePath"`
		TimeSyncedPath string `json:"timeSyncedPath"`
	} `json:"host"`
	// StatusReportSec: status.report interval before control suggests one (default 300).
	StatusReportSec int `json:"statusReportSec"`
	// SupportSocket is the support service's socket, read for status.report's `support` (remote help, MG-119). The Nix
	// module sets nothing (an older known-good manager refuses fields it doesn't know): default
	// /run/whombat-support/api.sock; "-" reads none.
	SupportSocket string `json:"supportSocket"`
	// SupportWatchSec: how often the support state is looked at for a change control should hear about at once
	// (default 10, MG-120).
	SupportWatchSec int `json:"supportWatchSec"`
	// BackupWatchSec: how often the backup service's status is looked at for a change the runtime should hear about at
	// once (default 15, MG-152). The Nix module sets nothing (an older known-good manager refuses fields it doesn't know).
	BackupWatchSec int `json:"backupWatchSec"`
	// TailscaleSocket is tailscaled's local API, which the manager drives for the runtime (CT-1255, MG-130). The Nix
	// module sets nothing (an older known-good manager refuses fields it doesn't know): default
	// /run/tailscale/tailscaled.sock; "-": this box has no Tailscale (the routes answer 404 unavailable).
	TailscaleSocket string `json:"tailscaleSocket"`
	Systemctl       string `json:"systemctl"`
	ReserveBytes    int64  `json:"reserveBytes"`
	// KnownGoodAfterSec is unused since W4-SEC part 2 (M-3): the known-good manager is resolved from the
	// update helper's TUF-verified records, no binary is copied. Accepted for old configurations.
	KnownGoodAfterSec int `json:"knownGoodAfterSec"`
	// PollSec: assignment poll interval before control suggests one (default 300).
	PollSec int `json:"pollSec"`
	// RefreshSec: TUF refresh interval (default 3600).
	RefreshSec int `json:"refreshSec"`
	// RuntimeProbeSec: how often the manager probes the runtime's health to notice a (re)start and hand it
	// the update facts and claim window again (default 10). FactsResendSec: those are also re-sent this often
	// while the runtime answers (default 300, jittered), in case a restart fell between two probes.
	RuntimeProbeSec int `json:"runtimeProbeSec"`
	FactsResendSec  int `json:"factsResendSec"`
	// ClaimWindowRequired: claiming needs a physical claim window (MA-04 §3); opening it is a
	// hardware event (button) wired by the image, not implemented here.
	ClaimWindowRequired bool `json:"claimWindowRequired"`
	// ClaimLookupRetrySec: first retry of a failed claim.lookup (default 15; doubles up to 5 min), MG-28.
	ClaimLookupRetrySec int `json:"claimLookupRetrySec"`
	// ClaimLookupOtherFamilyRetrySec: retry of a claim.lookup over the other address family that failed (default 30,
	// at most 10 in a row, then only with the renewals), MG-42.
	ClaimLookupOtherFamilyRetrySec int `json:"claimLookupOtherFamilyRetrySec"`
	// ReregisterRequest: where the manager asks root to give a retired, never-claimed self-installed
	// appliance new keys (MG-30; whombat-self-provision.service watches it). Empty: never.
	ReregisterRequest string `json:"reregisterRequest"`
	// Policy overrides (milliseconds; 0 = default). Production images leave these unset.
	Policy struct {
		HealthIntervalMs int `json:"healthIntervalMs"`
		VerifyTimeoutMs  int `json:"verifyTimeoutMs"`
		// HostRebootTimeoutMs: a host activation's reboot (default 20 min, MG-55); RollbackRetryBaseMs/MaxMs: the
		// backoff of a failing rollback step (default 5 s doubling to 10 min).
		HostRebootTimeoutMs int `json:"hostRebootTimeoutMs"`
		RollbackRetryBaseMs int `json:"rollbackRetryBaseMs"`
		RollbackRetryMaxMs  int `json:"rollbackRetryMaxMs"`
		DrainPollMs         int `json:"drainPollMs"`
		RetryBaseMs         int `json:"retryBaseMs"`
		IdleIntervalMs      int `json:"idleIntervalMs"`
		HealthyStreak       int `json:"healthyStreak"`
		MaxAttempts         int `json:"maxAttempts"`
	} `json:"policy"`
}

// SupportSocketDefault is the support service's socket (contracts 0.120.0 local.SupportSocketDefault).
const SupportSocketDefault = local.SupportSocketDefault

// TailscaleSocketDefault is tailscaled's local API in the image (nix/modules/tailscale.nix, NX-441).
const TailscaleSocketDefault = "/run/tailscale/tailscaled.sock"

// TargetsLayoutGitHub is tuf.targetsLayout of the GitHub repository (tufclient.LayoutGitHub).
const TargetsLayoutGitHub = "github"

// EnvTargetsLayout carries tuf.targetsLayout when the file has none. The image puts the layout in both manager units'
// environment, not in manager.json: the recovery unit may run the known-good manager of an earlier release with this
// same file, and that manager refuses every key it doesn't know (DisallowUnknownFields), so it couldn't start.
const EnvTargetsLayout = "WHOMBAT_TUF_TARGETS_LAYOUT"

// The editions (Whombat HE-58).
const (
	EditionCommercial = "commercial"
	EditionCommunity  = "community"
)

// Community reports whether this is a community box: no control, updates from its own repository (MG-136).
func (c *Config) Community() bool { return c.Edition == EditionCommunity }

// Device is /persist/identity/device.json (written at provisioning).
type Device struct {
	DeviceID string `json:"deviceId"`
	Env      string `json:"env"`
	Model    string `json:"model"` // "self-installed" for a self-registered appliance (CC-10)
}

// Load reads and validates the configuration.
func Load(path string) (*Config, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var c Config
	dec := json.NewDecoder(strings.NewReader(string(b)))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&c); err != nil {
		return nil, fmt.Errorf("manager config: %w", err)
	}
	switch c.Edition {
	case "":
		c.Edition = EditionCommercial
	case EditionCommercial, EditionCommunity:
	default:
		return nil, fmt.Errorf("manager config: unknown edition %q", c.Edition)
	}
	required := map[string]string{
		"deviceFile": c.DeviceFile, "managementKey": c.ManagementKey,
		"tuf.pinnedRoot": c.TUF.PinnedRoot, "tuf.metadataUrl": c.TUF.MetadataURL, "tuf.targetsUrl": c.TUF.TargetsURL,
		"tuf.cacheDir": c.TUF.CacheDir, "tuf.mirrorDir": c.TUF.MirrorDir, "stagingDir": c.StagingDir,
		"journalDir": c.JournalDir, "assignmentPath": c.AssignmentPath, "knownGoodDir": c.KnownGoodDir,
		"helperSocket": c.HelperSocket, "apiSocket": c.APISocket, "runtime.adminSocket": c.Runtime.AdminSocket,
	}
	if c.Community() {
		if c.Control.URL != "" {
			return nil, errors.New("manager config: a community box has no control (control.url must be empty)")
		}
	} else {
		required["control.url"] = c.Control.URL
	}
	for name, v := range required {
		if v == "" {
			return nil, fmt.Errorf("manager config: %s is required", name)
		}
	}
	if c.TUF.TargetsLayout == "" {
		c.TUF.TargetsLayout = os.Getenv(EnvTargetsLayout)
	}
	if c.TUF.TargetsLayout != "" && c.TUF.TargetsLayout != TargetsLayoutGitHub {
		return nil, fmt.Errorf("manager config: unknown tuf.targetsLayout %q", c.TUF.TargetsLayout)
	}
	if c.Clients.Root != "" && (c.Clients.StateDir == "" || c.Clients.ChannelKeys == "") {
		return nil, errors.New("manager config: clients.root needs clients.stateDir and clients.channelKeys")
	}
	if c.Licence.KeysFile != "" && c.Licence.StateFile == "" {
		c.Licence.StateFile = filepath.Join(filepath.Dir(filepath.Clean(c.JournalDir)), "licence.json")
	}
	if c.Metrics.Dir == "" {
		c.Metrics.Dir = filepath.Join(filepath.Dir(filepath.Clean(c.JournalDir)), "metrics")
	}
	if c.Metrics.PersistDir == "" {
		c.Metrics.PersistDir = filepath.Dir(filepath.Dir(filepath.Clean(c.JournalDir)))
	}
	if c.Host.BootIDPath == "" {
		c.Host.BootIDPath = "/proc/sys/kernel/random/boot_id"
	}
	if c.Host.CurrentSystem == "" {
		c.Host.CurrentSystem = "/run/current-system"
	}
	if c.Host.UptimePath == "" {
		c.Host.UptimePath = "/proc/uptime"
	}
	if c.Host.TimeSyncedPath == "" {
		c.Host.TimeSyncedPath = "/run/systemd/timesync/synchronized"
	}
	if c.Systemctl == "" {
		c.Systemctl = "/run/current-system/sw/bin/systemctl"
	}
	switch c.SupportSocket {
	case "":
		c.SupportSocket = SupportSocketDefault
	case "-":
		c.SupportSocket = ""
	}
	switch c.TailscaleSocket {
	case "":
		c.TailscaleSocket = TailscaleSocketDefault
	case "-":
		c.TailscaleSocket = ""
	}
	if c.ManagerVersion == "" {
		c.ManagerVersion = "0.0.0-dev"
	}
	return &c, nil
}

// TailscaleWantFile is where the manager keeps Tailscale wanted on until its first sign-in (tailscale.Config.WantFile),
// beside the journal like licence.json.
func (c *Config) TailscaleWantFile() string {
	return filepath.Join(filepath.Dir(filepath.Clean(c.JournalDir)), "tailscale.json")
}

// LoadDevice reads the device identity file.
func LoadDevice(path string) (*Device, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var d Device
	if err := json.Unmarshal(b, &d); err != nil {
		return nil, err
	}
	if d.DeviceID == "" || (d.Env != "local" && d.Env != "dev" && d.Env != "prod") {
		return nil, errors.New("device file: deviceId and env (local|dev|prod) required")
	}
	return &d, nil
}

// Seconds returns d seconds or def.
func Seconds(v int, def time.Duration) time.Duration {
	if v <= 0 {
		return def
	}
	return time.Duration(v) * time.Second
}
